using AcxiomCRM.Web.Data;using AcxiomCRM.Web.Models;using AcxiomCRM.Web.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Web.Controllers;
[Authorize]public class ActivitiesController:Controller{readonly ApplicationDbContext db;readonly UserManager<ApplicationUser> um;readonly AuditService audit;public ActivitiesController(ApplicationDbContext d,UserManager<ApplicationUser> u,AuditService a){db=d;um=u;audit=a;}string U=>um.GetUserId(User)!;bool Priv=>User.IsInRole("Admin")||User.IsInRole("Manager");public async Task<IActionResult>Index(){var x=db.Activities.Include(a=>a.Customer).Include(a=>a.Lead).Include(a=>a.AssignedTo).AsQueryable();if(!Priv)x=x.Where(a=>a.AssignedToId==U);return View(await x.OrderByDescending(a=>a.ActivityDate).ToListAsync());}public IActionResult Create()=>View(new ActivityVm());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(ActivityVm vm){if(!ModelState.IsValid)return View(vm);var a=new Activity{ActivityType=vm.ActivityType,Subject=vm.Subject,Description=vm.Description,ActivityDate=vm.ActivityDate,CustomerId=vm.CustomerId,LeadId=vm.LeadId,Status=vm.Status,AssignedToId=Priv&&vm.AssignedToId!=null?vm.AssignedToId:U};db.Activities.Add(a);await db.SaveChangesAsync();await audit.LogAsync("CREATE","Activity",a.Id.ToString(),null,a.Subject,U);return RedirectToAction(nameof(Index));}}
